// Title: Export Excel cell comments to HTML with Aspose.Cells while applying TableCssId‑prefixed table styles (C#)
// Common Searches: Aspose.Cells C# export worksheet to HTML including cell comments | How to preserve Excel comments in HTML output using HtmlSaveOptions | Apply custom TableCssId to HTML tables generated by Aspose.Cells | C# generate HTML from workbook with comments and prefixed CSS id | Aspose.Cells HtmlSaveOptions TableCssId comments not showing
// Tags: Aspose.Cells HtmlSaveOptions TableCssId | export Excel comments to HTML C# | include cell comments in HTML export | custom table CSS identifier Aspose.Cells | preserve worksheet comments in HTML output

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// The example creates a workbook, adds a comment to cell A2, sets HtmlSaveOptions.TableCssId to "myTable", and saves the workbook as an HTML file, ensuring that cell comments are included and the table inherits the specified CSS identifier.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook
            Workbook workbook = new Workbook();

            // Access the first worksheet and set its name
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Name = "Data";

            // Populate some cells
            sheet.Cells["A1"].PutValue("Header");
            sheet.Cells["A2"].PutValue("Value1");
            sheet.Cells["A3"].PutValue("Value2");

            // Add a comment to cell A2
            int commentIndex = sheet.Comments.Add("A2");
            Comment comment = sheet.Comments[commentIndex];
            comment.Note = "This is a comment for A2";

            // Configure HTML export options
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html)
            {
                // Prefix table styles with this ID
                TableCssId = "myTable"
            };

            // Ensure the output directory exists
            string outputPath = "output.html";
            string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));

            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Export the workbook to HTML
            workbook.Save(outputPath, htmlOptions);
            Console.WriteLine($"Workbook successfully saved to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
